from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
old = '<div className="wallet-breakdown"><span><small>قيمة الخدمة</small><strong>{activeServicePrice} ر.س</strong></span><span><small>نسبة نجدة (١٠٪)</small><strong>{activePlatformFee} ر.س</strong></span><span><small>صافي مقدم الخدمة</small><strong>{activeProviderNet} ر.س</strong></span></div>{paymentStatus === "pending" && <><p>يدفع العميل مسبقًا إلى محفظة الموقع، ويبقى المبلغ محجوزًا حتى تأكيد الإتمام.</p><button onClick={holdPayment} disabled={holdWalletFunds.isPending}>{holdWalletFunds.isPending ? "جارٍ الحجز..." : "حجز المبلغ من المحفظة"}</button></>}'
new = '<div className="wallet-balance-line"><span>الرصيد المتاح في محفظتك</span><strong>{walletQuery.data ? `${(walletQuery.data.wallet.availableHalalas / 100).toFixed(2)} ر.س` : "يتطلب تسجيل الدخول"}</strong></div><div className="wallet-breakdown"><span><small>قيمة الخدمة</small><strong>{activeServicePrice} ر.س</strong></span><span><small>نسبة نجدة (١٠٪)</small><strong>{activePlatformFee} ر.س</strong></span><span><small>صافي مقدم الخدمة</small><strong>{activeProviderNet} ر.س</strong></span></div>{paymentStatus === "pending" && <><p>{contactUnlocked ? "يدفع العميل مسبقًا إلى محفظة الموقع، ويبقى المبلغ محجوزًا حتى تأكيد الإتمام." : "بعد اتفاق الطرفين على السعر، أكّد الاتفاق لفتح خطوة حجز المبلغ."}</p><button onClick={holdPayment} disabled={holdWalletFunds.isPending || !contactUnlocked}>{holdWalletFunds.isPending ? "جارٍ الحجز..." : contactUnlocked ? "حجز المبلغ من المحفظة" : "بانتظار تأكيد الاتفاق"}</button></>}'
if old not in s: raise SystemExit('wallet card segment not found')
p.write_text(s.replace(old, new, 1))
